def count_Pairs(arr, n):
    counts = {}
    for x in arr[:n]:
        counts[x] = counts.get(x, 0) + 1

    total_pairs = n * (n - 1) // 2
    equal_pairs = sum(c * (c - 1) // 2 for c in counts.values())
    return total_pairs - equal_pairs
